final class TokenGranterMediatorUnitTest extends TestCase
{
    public function test_routes_client_credentials_to_correct_granter(): void
    {
        $mediator = $this->buildMediator();
        $client = new ClientData('svc', ['client_credentials'], true, ['api:read'], 3600);
        $req = new AuthenticationRequest($client, '', '');

        $result = $mediator->authenticate('client_credentials', 'tenant', $req, ['scope' => 'api:read']);

        $this->assertNotNull($result);
        $this->assertTrue($result->valid);
    }

    public function test_routes_password_grant(): void
    {
        $mediator = $this->buildMediator();
        $client = new ClientData('c', ['password'], true);
        $req = new AuthenticationRequest($client, '', '');

        $result = $mediator->authenticate('password', 'tenant', $req, [
            'username' => 'user@x.com',
            'password' => 'pass',
        ]);

        $this->assertNotNull($result);
    }

    public function test_returns_null_for_unknown_grant_type(): void
    {
        $mediator = $this->buildMediator();
        $client = new ClientData('c', [], true);
        $req = new AuthenticationRequest($client, '', '');

        $result = $mediator->authenticate('unknown_grant', 'tenant', $req, []);

        $this->assertNull($result);
    }

